/// Installs the sprite and object tables into the runtime registries.
pub fn install() bool {
    return runtime.SpriteRegistry.get().initRegistry(&sprites) and
        runtime.ObjectRegistry.get().initRegistry(&objects);
}

/// Installs the room table and room order (objects must be installed first).
